import{_ as d,a0 as r,w as n,s as p,ao as l,I as t,x as e,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"网络广告商的像素追踪是如何工作的？ | LCTT x X-CMD","titleTemplate":false,"description":"网络广告商的像素追踪是如何工作的？ | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"网络广告商的像素追踪是如何工作的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"网络广告商的像素追踪是如何工作的？ | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191218 How tracking pixels work","title":"网络广告商的像素追踪是如何工作的？","tag":"201912","desc":""},"relativePath":"201912/20191218 How tracking pixels work.md","filePath":"[post].md"}'),c={name:"201912/20191218 How tracking pixels work.md"};function k(f,o,m,g,b,x){const a=r("Link");return n(),p("div",null,[o[29]||(o[29]=l('<h1 id="网络广告商的像素追踪是如何工作的" tabindex="-1">网络广告商的像素追踪是如何工作的？ <a class="header-anchor" href="#网络广告商的像素追踪是如何工作的" aria-label="Permalink to “网络广告商的像素追踪是如何工作的？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/27/214125hvpv4e5ijepa0aqj.jpg" alt=""></p><p>昨天，我和一名记者谈到了一个问题：广告商是如何在互联网上对人们进行追踪的？我们津津有味地查看了 Firefox 的开发者工具（虽然我不是一个互联网隐私专家，但至少还会使用开发者工具中的“network”标签页），从中我终于弄明白<ruby>像素追踪<rt>tracking pixels</rt></ruby>在实际中是如何工作的了。</p><h3 id="问题-facebook-怎么知道你逛了-old-navy" tabindex="-1">问题：Facebook 怎么知道你逛了 Old Navy？ <a class="header-anchor" href="#问题-facebook-怎么知道你逛了-old-navy" aria-label="Permalink to “问题：Facebook 怎么知道你逛了 Old Navy？”">​</a></h3><p>我时常听人们说起这种有些诡异的上网经历：你在线上浏览了一个商品，一天之后，竟然看到了同一款靴子（或者是别的什么你当时浏览的商品）的广告。这就是所谓的“再营销”，但它到底是如何实现的呢？</p><p>在本文中，我们来进行一个小实验，看看 Facebook 究竟是怎么知道你在线上浏览了什么商品的。这里使用 Facebook 作为示例，只是因为很容易找到使用了 Facebook 像素追踪技术的网站；其实，几乎所有互联网广告公司都会使用类似的追踪技术。</p><h3 id="准备-允许第三方追踪器-同时关闭广告拦截器" tabindex="-1">准备：允许第三方追踪器，同时关闭广告拦截器 <a class="header-anchor" href="#准备-允许第三方追踪器-同时关闭广告拦截器" aria-label="Permalink to “准备：允许第三方追踪器，同时关闭广告拦截器”">​</a></h3><p>我使用的浏览器是 Firefox，但是 Firefox 默认拦截了很多这种类型的追踪，所以需要修改 Firefox 的隐私设置，才能让这种追踪生效。</p>',8)),t("p",null,[o[2]||(o[2]=e("首先，我将隐私设置从默认设置（",-1)),i(a,{href:"https://jvns.ca/images/trackers.png"},{default:s(()=>[...o[0]||(o[0]=[e("截图",-1)])]),_:1}),o[3]||(o[3]=e("）修改为允许第三方追踪器的个性化设置（",-1)),i(a,{href:"https://jvns.ca/images/firefox-insecure-settings.png"},{default:s(()=>[...o[1]||(o[1]=[e("截图",-1)])]),_:1}),o[4]||(o[4]=e("），然后禁用了一些平时运行的隐私保护扩展。",-1))]),o[30]||(o[30]=l('<p><img src="https://jvns.ca/images/trackers.png" alt="截图"></p><p><img src="https://jvns.ca/images/firefox-insecure-settings.png" alt="截图"></p><h3 id="像素追踪-关键不在于-gif-而在于请求参数" tabindex="-1">像素追踪：关键不在于 gif，而在于请求参数 <a class="header-anchor" href="#像素追踪-关键不在于-gif-而在于请求参数" aria-label="Permalink to “像素追踪：关键不在于 gif，而在于请求参数”">​</a></h3><p>像素追踪是网站用来追踪你的一个 1x1 大小的 gif。就其本身而言，一个小小的 1x1 gif 显然起不到什么作用。那么，像素追踪到底是如何进行追踪的？其中涉及两个方面：</p><ol><li>通过使用像素追踪上的<strong>请求参数</strong>，网站可以添加额外的信息，比如你正在访问的页面。这样一来，请求的就不是 <code>https://www.facebook.com/tr/</code>（这个链接是一个 44 字节大小的 1x1 gif），而是 <code>https://www.facebook.com/tr/?the_website_you&#39;re_on</code>。（邮件营销人员会使用类似的技巧，通过为像素追踪指定一个独特的 URL，弄清楚你是否打开了某一封邮件。）</li><li>在发送该请求的同时，还发送了相应的 cookie。这样一来广告商就可以知道，访问 oldnavy.com 的这个人和在同一台电脑上使用 Facebook 的是同一个人。</li></ol><h3 id="old-navy-网站上的-facebook-像素追踪" tabindex="-1">Old Navy 网站上的 Facebook 像素追踪 <a class="header-anchor" href="#old-navy-网站上的-facebook-像素追踪" aria-label="Permalink to “Old Navy 网站上的 Facebook 像素追踪”">​</a></h3><p>为了对此进行验证，我在 Old Navy（GAP 旗下的一个服装品牌）网站上浏览了一个商品，相应的 URL 是 <code>https://oldnavy.gap.com/browse/product.do?pid=504753002&amp;cid=1125694&amp;pcid=1135640&amp;vid=1&amp;grid=pds_0_109_1</code>（这是一件“男款短绒格子花呢大衣”）。</p>',7)),t("p",null,[o[6]||(o[6]=e("在我浏览这个商品的同时，页面上运行的 Javascript（用的应该是",-1)),i(a,{href:"https://developers.facebook.com/docs/facebook-pixel/implementation/"},{default:s(()=>[...o[5]||(o[5]=[e("这段代码",-1)])]),_:1}),o[7]||(o[7]=e("）向 facebook.com 发送了一个请求。在开发者工具中，该请求看上去是这样的：（我屏蔽了大部分 cookie 值，因为其中有一些是我的登录 cookie）",-1))]),o[31]||(o[31]=l('<p><img src="https://jvns.ca/images/fb-old-navy.png" alt=""></p><p>下面对其进行拆解分析：</p><ol><li><p>我的浏览器向如下 URL 发送了一个请求；</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ol>',3)),t("p",null,[i(a,{href:"https://www.facebook.com/tr/?id=937725046402747&ev=PageView&dl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fproduct.do%3Fpid%3D504753002%26cid%3D1125694%26pcid%3Dxxxxxx0%26vid%3D1%26grid%3Dpds_0_109_1%23pdp-page-content&rl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fcategory.do%3Fcid%3D1135640%26mlink%3D5155%2Cm_mts_a&if=false&ts=1576684838096&sw=1920&sh=1080&v=2.9.15&r=stable&a=tmtealium&ec=0&o=30&fbp=fb.1.1576684798512.1946041422&it=15xxxxxxxxxx4&coo=false&rqm=GET"},{default:s(()=>[...o[8]||(o[8]=[e("https://www.facebook.com/tr/?id=937725046402747&ev=PageView&dl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fproduct.do%3Fpid%3D504753002%26cid%3D1125694%26pcid%3Dxxxxxx0%26vid%3D1%26grid%3Dpds_0_109_1%23pdp-page-content&rl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fcategory.do%3Fcid%3D1135640%26mlink%3D5155%2Cm_mts_a&if=false&ts=1576684838096&sw=1920&sh=1080&v=2.9.15&r=stable&a=tmtealium&ec=0&o=30&fbp=fb.1.1576684798512.1946041422&it=15xxxxxxxxxx4&coo=false&rqm=GET",-1)])]),_:1})]),o[32]||(o[32]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2. 与该请求同时发送的，还有一个名为 `fr` 的 cookie，取值为</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>    ```</span></span>\n<span class="line"><span>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</span></span></code></pre></div><p>（估计是我的 Facebook 广告追踪 ID）</p><p>在所发送的像素追踪查询字符串里，有三个值得注意的地方：</p><ul><li>我当前访问的页面：<code>https://oldnavy.gap.com/browse/product.do?pid=504753002&amp;cid=1125694&amp;pcid=1135640&amp;vid=1&amp;grid=pds_0_109_1#pdp-page-content</code></li><li>引导我来到当前页面的上一级页面：<code>https://oldnavy.gap.com/browse/category.do?cid=1135640&amp;mlink=5155,m_mts_a</code>；</li><li>作为我的身份标识的 cookie：<code>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</code></li></ul><h3 id="下面来逛逛-facebook" tabindex="-1">下面来逛逛 Facebook！ <a class="header-anchor" href="#下面来逛逛-facebook" aria-label="Permalink to “下面来逛逛 Facebook！”">​</a></h3><p>下面来逛逛 Facebook 吧。我之前已经登入了 Facebook，猜猜看，我的浏览器发送给 Facebook 的 cookie 是什么？</p><p>不出所料，正是之前见过的 <code>fr</code> cookie：<code>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</code>。Facebook 现在一定知道我（Julia Evans，这个 Facebook 账号所关联的人）在几分钟之前访问了 Old Navy 网站，并且浏览了“男款短绒格子花呢大衣”，因为他们可以使用这个 cookie 将数据串联起来。</p><h3 id="这里涉及到的是第三方-cookie" tabindex="-1">这里涉及到的是第三方 cookie <a class="header-anchor" href="#这里涉及到的是第三方-cookie" aria-label="Permalink to “这里涉及到的是第三方 cookie”">​</a></h3><p>Facebook 用来追踪我访问了哪些网站的 cookie，属于所谓的“第三方 cookie”，因为 Old Navy 的网站使用它为一个第三方（即 facebook.com）确认我的身份。这和用来维持登录状态的“第一方 cookie”有所不同。</p><p>Safari 和 Firefox 默认都会拦截许多第三方 cookie（所以需要更改 Firefox 的隐私设置，才能够进行这个实验），而 Chrome 目前并不进行拦截（很可能是因为 Chrome 的所有者正是一个广告公司）。（LCTT 译注：Chrome 可以设置阻拦）</p><h3 id="网站上的像素追踪有很多" tabindex="-1">网站上的像素追踪有很多 <a class="header-anchor" href="#网站上的像素追踪有很多" aria-label="Permalink to “网站上的像素追踪有很多”">​</a></h3><p>如我所料，网站上的像素追踪有 <strong>很多</strong>。比如，wrangler.com 在我的浏览器里加载了来自不同域的 19 个不同的像素追踪。wrangler.com 上的像素追踪分别来自：<code>ct.pinterest.com</code>、<code>af.monetate.net</code>、<code>csm.va.us.criteo.net</code>、<code>google-analytics.com</code>、<code>dpm.demdex.net</code>、<code>google.ca</code>、<code>a.tribalfusion.com</code>、<code>data.photorank.me</code>、<code>stats.g.doubleclick.net</code>、<code>vfcorp.dl.sc.omtrdc.net</code>、<code>ib.adnxs.com</code>、<code>idsync.rlcdn.com</code>、<code>p.brsrvr.com</code>，以及 <code>adservice.google.com</code>。</p><p>Firefox 贴心地指出，如果使用 Firefox 的标准隐私设置，其中的大部分追踪器都会被拦截：</p><p><img src="https://jvns.ca/images/firefox-helpful.png" alt=""></p><h3 id="浏览器的重要性" tabindex="-1">浏览器的重要性 <a class="header-anchor" href="#浏览器的重要性" aria-label="Permalink to “浏览器的重要性”">​</a></h3><p>浏览器之所以如此重要，是因为你的浏览器最终决定了发送你的什么信息、发送到哪些网站。Old Navy 网站上的 Javascript 可以请求你的浏览器向 Facebook 发送关于你的追踪信息，但浏览器可以拒绝执行。浏览器的决定可以是：“哈，我知道 facebook.com/tr/ 是一个像素追踪，我不想让我的用户被追踪，所以我不会发送这个请求”。</p><p>浏览器还可以允许用户对上述行为进行配置，方法包括更改浏览器设置，以及安装浏览器扩展（所以才会有如此多的隐私保护扩展）。</p><h3 id="摸清其中原理-实为一件趣事" tabindex="-1">摸清其中原理，实为一件趣事 <a class="header-anchor" href="#摸清其中原理-实为一件趣事" aria-label="Permalink to “摸清其中原理，实为一件趣事”">​</a></h3><p>在我看来，弄清楚 cookie/像素追踪是怎么用于对你进行追踪的，实在是一件趣事（尽管有点吓人）。我之前大概明白其中的道理，但是并没有亲自查看过像素追踪上的 cookie，也没有看过发送的查询参数上究竟包含什么样的信息。</p><p>当然，明白了其中的原理，也就更容易降低被追踪的概率了。</p><h3 id="可以采取的措施" tabindex="-1">可以采取的措施 <a class="header-anchor" href="#可以采取的措施" aria-label="Permalink to “可以采取的措施”">​</a></h3><p>为了尽量避免在互联网上被追踪，我采取了几种简单的措施:</p>',22)),t("ul",null,[o[12]||(o[12]=t("li",null,"安装一个广告拦截器（比如 ublock origin 之类）。广告拦截器可以针对许多追踪器的域进行拦截。",-1)),o[13]||(o[13]=t("li",null,"使用目前默认隐私保护强度更高的 Firefox/Safari，而不是 Chrome。",-1)),t("li",null,[o[10]||(o[10]=e("使用 ",-1)),i(a,{href:"https://addons.mozilla.org/en-CA/firefox/addon/facebook-container/"},{default:s(()=>[...o[9]||(o[9]=[e("Facebook Container",-1)])]),_:1}),o[11]||(o[11]=e(" 这个 Firefox 扩展。该扩展针对 Facebook 进一步采取了防止追踪的措施。",-1))])]),o[33]||(o[33]=t("p",null,"虽然在互联网上被追踪的方式还有很多（尤其是在使用手机应用的时候，因为在这种情况下，你没有和像对浏览器一样的控制程度），但是能够理解这种追踪方法的工作原理，稍微减少一些被追踪的可能性，也总归是一件好事。",-1)),o[34]||(o[34]=t("hr",null,null,-1)),t("p",null,[o[15]||(o[15]=e("via: ",-1)),i(a,{href:"https://jvns.ca/blog/how-tracking-pixels-work/"},{default:s(()=>[...o[14]||(o[14]=[e("https://jvns.ca/blog/how-tracking-pixels-work/",-1)])]),_:1})]),t("p",null,[o[20]||(o[20]=e("作者：",-1)),i(a,{href:"https://jvns.ca/"},{default:s(()=>[...o[16]||(o[16]=[e("Julia Evans",-1)])]),_:1}),o[21]||(o[21]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:s(()=>[...o[17]||(o[17]=[e("lujun9972",-1)])]),_:1}),o[22]||(o[22]=e(" 译者：",-1)),i(a,{href:"https://github.com/chen-ni"},{default:s(()=>[...o[18]||(o[18]=[e("chen-ni",-1)])]),_:1}),o[23]||(o[23]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...o[19]||(o[19]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[26]||(o[26]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[24]||(o[24]=[e("LCTT",-1)])]),_:1}),o[27]||(o[27]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...o[25]||(o[25]=[e("Linux中国",-1)])]),_:1}),o[28]||(o[28]=e(" 荣誉推出",-1))])])}const F=d(c,[["render",k]]);export{v as __pageData,F as default};
